        return -1;
    }
    FILE *out = fopen(out_path, "w");
    if (!out) {
        fclose(in);
        free(map.syms);
        return -1;
    }
    fprintf(out, "{\n  \"frames\": [\n");
    char line[256];
    int first = 1;
    while (fgets(line, sizeof(line), in)) {
        unsigned long pc = 0;
        if (sscanf(line, "pc 0x%lx", &pc) != 1) {
