        }
        char sym[128] = {0};
        unsigned long off = 0;
        if (resolve_pc(&map, pc, sym, &off) != 0) {
            continue;
        }
        if (!first) {
            fprintf(out, ",\n");
        }
        fprintf(out, "    {\"pc\": \"0x%lx\", \"symbol\": \"%s\", \"offset\": %lu}", pc, sym, off);
        first = 0;
    }
    fprintf(out, "\n  ]\n}\n");
    fclose(in);
    fclose(out);
    free(map.syms);
    return 0;
}
